"""HOOKS.json: the list of the hooks of each folder of the series, generated by the export and checked.

STRUCTURE (coord/portabilita-69/STRUCTURE.md, section 5): every folder of SERIES that is not a backport
has a HOOKS.json beside its hooks.patch, one entry per hook. The export (and `python tools/engine.py
hooks-list`, which is the same function, `write_all`) writes it from the hooks.patch; `check` fails when
the committed file and the series differ, so a hook lost in a merge does not pass silently.

An entry, in this order of keys:

    file      the Mozilla file
    function  the host function (git's hunk header)
    kind      add | rewrite | delete | file   (a deletion and a whole-file removal are listed too: nothing is invisible)
    form      guard | notice | wrap-expression | wrap-function | declared-value | registration | member | anchor | unknown
    line      the added text ('' for a deletion)
    removed   the Mozilla line a rewrite replaces, or what a deletion takes away (left out for a pure addition)
    ---- written by hand, kept by the export ----
    test      the test that proves the hook ('' while there is none: that is debt, rule T1 of hook_contract)
    anchor    (form anchor only) the Mozilla statement the hook follows
    why       (form anchor only) why the guard, wrap-function and wrap-expression forms are not enough (rule T2)

Identity of a hook: file + function + kind + normalized line text (+ normalized removed text). The export
merges the hand fields into the generated list by identity; a hook whose text changes loses them on
purpose, and `check` asks for them again.

Test references (the grammar of `test`; '' is allowed and is debt):

    gtest:<Suite>.<Name>            some file under any folder's src/ has TEST(<Suite>, <Name>) or TEST_F(<Suite>, <Name>)
    node:<path>[#<test title>]      <path> is a tree path (juggler/tests/x.test.mjs): <folder>/src/<path> exists in some
                                    folder; with a title, the title string appears in the file
    py:<path>::<test_name>          the same for a python test of ours: the file exists and defines test_name
    wrapper:<path>::<test>          a test of the wrapper repository: only the format is checked here

Public API:

    generated(root, folder)           -> list[dict]   the entries the series generates for one folder
    merge(generated, committed)       -> list[dict]   generated entries with the hand fields of the committed ones
    expected(root, folder)            -> list[dict]   merge(generated, the committed file)
    render(entries)                   -> str          the text of a HOOKS.json
    write_all(root)                   -> dict         writes every HOOKS.json, folder -> number of entries
    problems(root)                    -> list[str]    what `check` reports
    reference_problem(root, ref)      -> str | None   why a test reference does not resolve
    missing_test_violations(root)     -> list[Violation]   rules T1 and T2 for hook_contract
"""
from __future__ import annotations

import json
import re
from pathlib import Path

import hook_contract as hc

HAND_FIELDS = ("test", "anchor", "why")
GTEST_RE = re.compile(r"\bTEST(?:_F)?\s*\(\s*(\w+)\s*,\s*(\w+)\s*\)")
GTEST_SUFFIXES = {".cpp", ".cc", ".cxx", ".h", ".hpp"}
WRAPPER_RE = re.compile(r"^wrapper:[^\s:#]+::\S+$")


# --------------------------------------------------------------------------- the folders
def series_names(root: Path) -> list:
    return (Path(root) / "SERIES").read_text(encoding="utf-8").split()


def folders(root: Path) -> list:
    """The folders of SERIES that carry a HOOKS.json: all but the backports (upstream code, its own rules)."""
    root = Path(root)
    return [f for f in series_names(root) if (root / f).is_dir() and not (root / f / "BACKPORT.json").exists()]


def list_path(root: Path, folder: str) -> Path:
    return Path(root) / folder / "HOOKS.json"


# --------------------------------------------------------------------------- generating
def _squeeze(t: str) -> str:
    return re.sub(r"\s+", " ", t.strip())


def identity(e: dict) -> tuple:
    return (e["file"], _squeeze(e["function"]), e["kind"], hc.norm(e["line"]), hc.norm(e.get("removed", "")))


def _entry(h: hc.Hook) -> dict:
    e = {"file": h.file, "function": h.function, "kind": h.kind, "form": h.form, "line": h.line}
    if h.removed:
        e["removed"] = h.removed
    return e


def generated(root: Path, folder: str) -> list:
    """One entry per hook of `folder`, in the order of its hooks.patch: file, function, kind, form, line (and
    removed). [] for a folder without a hooks.patch and for a backport."""
    root = Path(root)
    patch = root / folder / "hooks.patch"
    if not patch.is_file() or (root / folder / "BACKPORT.json").exists():
        return []
    hooks, _ = hc.analyse_patch(folder, patch.read_text(encoding="utf-8", errors="replace"))
    return [_entry(h) for h in hooks]


def _with_hand_fields(e: dict, old: dict | None) -> dict:
    out = dict(e)
    old = old or {}
    out["test"] = old.get("test", "")
    if e["form"] == "anchor":
        out["anchor"] = old.get("anchor", "")
        out["why"] = old.get("why", "")
    return out


def merge(gen: list, committed: list) -> list:
    """The generated entries, each with the hand fields (test, anchor, why) of the committed entry of the same
    identity; none where there is none. Two entries of one identity are paired in order."""
    pool = {}
    for c in committed or []:
        if isinstance(c, dict) and all(k in c for k in ("file", "function", "kind", "line")):
            pool.setdefault(identity(c), []).append(c)
    out = []
    for e in gen:
        same = pool.get(identity(e))
        out.append(_with_hand_fields(e, same.pop(0) if same else None))
    return out


def load(root: Path, folder: str):
    """The committed list of a folder, or None if there is no file."""
    path = list_path(root, folder)
    if not path.is_file():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


def expected(root: Path, folder: str) -> list:
    return merge(generated(root, folder), load(root, folder) or [])


def render(entries: list) -> str:
    return json.dumps(entries, indent=1, ensure_ascii=False) + "\n"


def write_all(root: Path) -> dict:
    """Writes the HOOKS.json of every folder (the export and `hooks-list` both come here). -> folder -> entries."""
    root = Path(root)
    counts = {}
    for folder in folders(root):
        entries = expected(root, folder)
        list_path(root, folder).write_text(render(entries), encoding="utf-8", newline="")
        counts[folder] = len(entries)
    return counts


# --------------------------------------------------------------------------- test references
class _Index:
    """What the folders' src/ trees hold, read once and only when a reference needs it."""

    def __init__(self, root: Path):
        self.root, self._gtests = Path(root), None

    def src_file(self, path: str):
        for folder in series_names(self.root):
            p = self.root / folder / "src" / path
            if p.is_file():
                return p
        return None

    def gtests(self) -> set:
        if self._gtests is None:
            found = set()
            for folder in series_names(self.root):
                src = self.root / folder / "src"
                if not src.is_dir():
                    continue
                for p in src.rglob("*"):
                    if p.suffix in GTEST_SUFFIXES and p.is_file():
                        text = p.read_text(encoding="utf-8", errors="replace")
                        if "TEST" in text:
                            found.update(GTEST_RE.findall(text))
            self._gtests = found
        return self._gtests


def reference_problem(root: Path, ref: str, index: _Index | None = None) -> str | None:
    """None if the test reference resolves, else the reason it does not (grammar in the module docstring)."""
    index = index or _Index(root)
    kind, _, rest = ref.partition(":")
    if kind == "gtest":
        suite, dot, name = rest.partition(".")
        if not (suite and dot and name) or not re.fullmatch(r"\w+", suite) or not re.fullmatch(r"\w+", name):
            return "gtest:<Suite>.<Name> expected"
        return None if (suite, name) in index.gtests() else "no TEST(%s, %s) or TEST_F(%s, %s) in any folder's src/" % (suite, name, suite, name)
    if kind == "node":
        path, _, title = rest.partition("#")
        if not path:
            return "node:<path>[#<title>] expected"
        p = index.src_file(path)
        if p is None:
            return "%s is in no folder's src/" % path
        if title and title not in p.read_text(encoding="utf-8", errors="replace"):
            return "the title %r is not in %s" % (title, path)
        return None
    if kind == "py":
        path, sep, name = rest.partition("::")
        if not (path and sep and name):
            return "py:<path>::<test_name> expected"
        p = index.src_file(path)
        if p is None:
            return "%s is in no folder's src/" % path
        if not re.search(r"\bdef\s+%s\b" % re.escape(name), p.read_text(encoding="utf-8", errors="replace")):
            return "%s does not define %s" % (path, name)
        return None
    if kind == "wrapper":
        return None if WRAPPER_RE.match(ref) else "wrapper:<path>::<test> expected"
    return "unknown test reference %r: gtest:, node:, py: or wrapper:" % ref


# --------------------------------------------------------------------------- the check
def _label(e: dict) -> str:
    text = e.get("line") or ("<%s> %s" % (e.get("kind", "?"), _squeeze(e.get("removed", ""))))
    return "%s, %s: %s" % (e.get("file", "?"), _squeeze(e.get("function", ""))[:60], _squeeze(text)[:100])


def _diff(folder: str, gen: list, committed: list) -> list:
    """The differences between the committed list and the generation (hand fields are not compared)."""
    found, pool = [], {}
    for c in committed:
        pool.setdefault(identity(c), []).append(c)
    matched = []
    for e in gen:
        same = pool.get(identity(e))
        if not same:
            found.append("%s/HOOKS.json lacks the hook %s: python tools/engine.py hooks-list" % (folder, _label(e)))
            continue
        c = same.pop(0)
        matched.append(c)
        for k in ("form", "kind", "removed", "line", "function", "file"):
            if c.get(k, "") != e.get(k, ""):
                found.append("%s/HOOKS.json: the hook %s has %s %r, the series generates %r"
                             % (folder, _label(e), k, c.get(k, ""), e.get(k, "")))
    for rest in pool.values():
        for c in rest:
            found.append("%s/HOOKS.json lists the hook %s, which hooks.patch no longer has: python tools/engine.py hooks-list"
                         % (folder, _label(c)))
    return found


def problems(root: Path) -> list:
    """What `check` reports: a folder whose committed HOOKS.json differs from what its hooks.patch generates (missing
    file, a hook missing or extra, a field changed, the order) and a `test` that names a test that does not exist."""
    root, found = Path(root), []
    index = _Index(root)
    for folder in folders(root):
        try:
            committed = load(root, folder)
        except ValueError as exc:
            found.append("%s/HOOKS.json is not JSON: %s" % (folder, exc))
            continue
        if committed is None:
            found.append("%s/HOOKS.json is missing: python tools/engine.py hooks-list" % folder)
            continue
        if not isinstance(committed, list) or not all(isinstance(c, dict) and all(k in c for k in ("file", "function", "kind", "line"))
                                                      for c in committed):
            found.append("%s/HOOKS.json is not a list of hook entries: python tools/engine.py hooks-list" % folder)
            continue
        gen = generated(root, folder)
        diff = _diff(folder, gen, committed)
        found += diff
        if not diff and render(merge(gen, committed)) != render(committed):
            found.append("%s/HOOKS.json differs from what the series generates (order or a key): python tools/engine.py hooks-list"
                         % folder)
        for c in committed:
            ref = c.get("test", "")
            if not isinstance(ref, str):
                found.append("%s/HOOKS.json: the test of the hook %s is not a string" % (folder, _label(c)))
            elif ref:
                why = reference_problem(root, ref, index)
                if why:
                    found.append("%s/HOOKS.json: the hook %s names the test %s, which does not exist: %s"
                                 % (folder, _label(c), ref, why))
    return found


# --------------------------------------------------------------------------- the debt (rules T1, T2)
def missing_test_violations(root: Path) -> list:
    """T1 for every hook whose entry has no `test`, T2 for every anchor entry without `anchor` or `why`, from the
    series merged with the committed hand fields (so a missing file makes every hook a T1)."""
    found = []
    for folder in folders(root):
        for e in expected(root, folder):
            text = e["line"] or ("<%s> %s" % (e["kind"], e.get("removed", "")))
            if not e.get("test"):
                found.append(hc.Violation("T1", folder, e["file"], e["function"], text,
                                          hc._key("T1", folder, e["file"], e["function"], text), "no test"))
            if e["form"] == "anchor" and not (e.get("anchor") and e.get("why")):
                found.append(hc.Violation("T2", folder, e["file"], e["function"], text,
                                          hc._key("T2", folder, e["file"], e["function"], text), "no anchor or why"))
    return hc._unique(found)


def summary_line(counts: dict) -> str:
    return "%d HOOKS.json files, %d entries" % (len(counts), sum(counts.values()))

